(** Nonhalting of 1RB1LB_1RC0LA_1RD0RE_1LA0LB_1RF---_1RB1LD.

    The proof is a reflective checker for accelerated runs over 4-cell blocks: configurations
    are lists of (word, exponent) on each side of the head, exponents are affine forms in
    natural-number parameters, and a run is a list of block/chain moves interleaved with
    "Diff rules" (a fixed configuration skeleton whose exponents change by constants), each of
    which is proved on the spot by a nested symbolic run and then applied as many times as its
    decreasing exponents allow.  [run_spec] proves the checker sound against the busycoq step
    relation; the certificates below are replayed with vm_compute.

    With N(Y) = 0^inf 0001 1011^Y <A 0001^28 0011 0000 1000 0^inf:
      - from the blank tape the machine reaches N(508932094);
      - N(m + 22) -->+ N(2^18 m + 38626190) for every m.
    So it visits N(Y) with Y >= 22 forever.

    AI assistance: this proof sketch, the scripts and the checks were produced with the help of
    Claude (Anthropic). *)

From BusyCoq Require Import Individual62.
From Coq Require Import Arith Lia List NArith PArith ZArith Bool.
Import ListNotations.

Open Scope N_scope.

(** * Affine forms over natural-number variables *)

Definition coefs := list (N * positive).
Record lin := LN { lc : N; lv : coefs }.

Fixpoint sumc (rho : N -> N) (l : coefs) : N :=
  match l with
  | [] => 0
  | (v, a) :: l' => Npos a * rho v + sumc rho l'
  end.

Definition ev (rho : N -> N) (e : lin) : N := lc e + sumc rho (lv e).

Fixpoint cadd (a : coefs) : coefs -> coefs :=
  match a with
  | [] => fun b => b
  | (v, x) :: a' =>
    fix go (b : coefs) : coefs :=
      match b with
      | [] => a
      | (w, y) :: b' =>
        match N.compare v w with
        | Eq => (v, (x + y)%positive) :: cadd a' b'
        | Lt => (v, x) :: cadd a' b
        | Gt => (w, y) :: go b'
        end
      end
  end.

Lemma sumc_cadd rho a b : sumc rho (cadd a b) = sumc rho a + sumc rho b.
Proof.
  revert b; induction a as [| [v x] a IH]; intros b; [reflexivity |].
  induction b as [| [w y] b IHb]; cbn - [N.mul N.add N.sub]; [lia |].
  destruct (N.compare_spec v w) as [Hc | Hc | Hc]; cbn - [N.mul N.add N.sub].
  - subst w. rewrite IH. assert (Npos (x + y) = Npos x + Npos y) as -> by lia. nia.
  - rewrite IH. cbn - [N.mul N.add N.sub]. lia.
  - cbn - [N.mul N.add N.sub] in IHb. rewrite IHb. lia.
Qed.

Definition cscale (k : positive) (a : coefs) : coefs :=
  map (fun '(v, x) => (v, (x * k)%positive)) a.

Lemma sumc_cscale rho k a : sumc rho (cscale k a) = sumc rho a * Npos k.
Proof.
  unfold cscale. induction a as [| [v x] a IH]; cbn - [N.mul N.add N.sub]; [reflexivity |].
  rewrite IH. assert (Npos (x * k) = Npos x * Npos k) as -> by lia. nia.
Qed.

Fixpoint csub (a : coefs) : coefs -> option coefs :=
  match a with
  | [] => fun b => match b with [] => Some [] | _ => None end
  | (v, x) :: a' => fun b =>
    match b with
    | [] => Some a
    | (w, y) :: b' =>
      match N.compare v w with
      | Eq =>
        match Pos.compare x y with
        | Eq => csub a' b'
        | Gt => match csub a' b' with Some c => Some ((v, (x - y)%positive) :: c) | None => None end
        | Lt => None
        end
      | Lt => match csub a' b with Some c => Some ((v, x) :: c) | None => None end
      | Gt => None
      end
    end
  end.

Lemma sumc_csub rho a b c : csub a b = Some c -> sumc rho a = sumc rho b + sumc rho c.
Proof.
  revert b c; induction a as [| [v x] a IH]; intros b c H.
  - destruct b; cbn - [N.mul N.add N.sub] in H; inversion H; subst; reflexivity.
  - destruct b as [| [w y] b]; cbn - [N.mul N.add N.sub] in H.
    + inversion H; subst; cbn - [N.mul N.add N.sub]; lia.
    + destruct (N.compare_spec v w) as [Hc | Hc | Hc]; [subst w | | discriminate].
      * destruct (Pos.compare_spec x y) as [Hf | Hf | Hf].
        -- subst y. apply IH in H. cbn - [N.mul N.add N.sub]. lia.
        -- discriminate.
        -- destruct (csub a b) eqn:Hs; inversion H; subst.
           apply IH in Hs. cbn - [N.mul N.add N.sub]. assert (Npos (x - y) = Npos x - Npos y) as -> by lia. nia.
      * destruct (csub a ((w, y) :: b)) eqn:Hs; inversion H; subst.
        apply IH in Hs. cbn - [N.mul N.add N.sub] in *. lia.
Qed.

Fixpoint cdiv (a : coefs) (d : positive) : option coefs :=
  match a with
  | [] => Some []
  | (v, x) :: a' =>
    match N.div_eucl (Npos x) (Npos d) with
    | (Npos q, 0) => match cdiv a' d with Some c => Some ((v, q) :: c) | None => None end
    | _ => None
    end
  end.

Lemma sumc_cdiv rho a d c : cdiv a d = Some c -> sumc rho a = Npos d * sumc rho c.
Proof.
  revert c; induction a as [| [v x] a IH]; intros c H; cbn [cdiv] in H.
  - inversion H; subst; cbn - [N.mul N.add N.sub]; lia.
  - pose proof (N.div_eucl_spec (Npos x) (Npos d)) as Hs.
    destruct (N.div_eucl (Npos x) (Npos d)) as [[| q] [| r]]; cbn [fst snd] in H; try discriminate.
    destruct (cdiv a d) eqn:Hc; inversion H; subst.
    specialize (IH _ eq_refl). cbn - [N.mul N.add N.sub]. rewrite IH. rewrite Hs. nia.
Qed.

Definition lconst (k : N) : lin := LN k [].
Definition ladd (a b : lin) : lin := LN (lc a + lc b) (cadd (lv a) (lv b)).
Definition lscale (e : lin) (k : N) : lin :=
  match k with
  | 0 => LN 0 []
  | Npos p => LN (lc e * Npos p) (cscale p (lv e))
  end.
Definition lsub (a b : lin) : option lin :=
  if lc b <=? lc a then
    match csub (lv a) (lv b) with Some c => Some (LN (lc a - lc b) c) | None => None end
  else None.
Definition lsubc (a : lin) (k : N) : option lin :=
  if k <=? lc a then Some (LN (lc a - k) (lv a)) else None.
Definition lle (a b : lin) : bool := match lsub b a with Some _ => true | None => false end.
Definition ldiv (a : lin) (d : positive) : option lin :=
  match cdiv (lv a) d with Some c => Some (LN (lc a / Npos d) c) | None => None end.

Fixpoint ceqb (a b : coefs) : bool :=
  match a, b with
  | [], [] => true
  | (v, x) :: a', (w, y) :: b' => N.eqb v w && Pos.eqb x y && ceqb a' b'
  | _, _ => false
  end.
Definition leqb (a b : lin) : bool := N.eqb (lc a) (lc b) && ceqb (lv a) (lv b).
Definition lzero (e : lin) : bool := match e with LN 0 [] => true | _ => false end.

Lemma ceqb_eq a b : ceqb a b = true -> a = b.
Proof.
  revert b; induction a as [| [v x] a IH]; intros [| [w y] b] H; cbn in H; try discriminate; [reflexivity |].
  apply andb_prop in H as [H H3]. apply andb_prop in H as [H1 H2].
  apply N.eqb_eq in H1. apply Pos.eqb_eq in H2. apply IH in H3. subst. reflexivity.
Qed.

Lemma leqb_eq a b : leqb a b = true -> a = b.
Proof.
  destruct a, b; unfold leqb; cbn. intros H. apply andb_prop in H as [H1 H2].
  apply N.eqb_eq in H1. apply ceqb_eq in H2. subst. reflexivity.
Qed.

Lemma ev_lconst rho k : ev rho (lconst k) = k.
Proof. unfold ev; cbn; lia. Qed.
Lemma ev_ladd rho a b : ev rho (ladd a b) = ev rho a + ev rho b.
Proof. unfold ev, ladd; cbn. rewrite sumc_cadd. lia. Qed.
Lemma ev_lscale rho e k : ev rho (lscale e k) = ev rho e * k.
Proof. destruct k; unfold ev; cbn; [lia |]. rewrite sumc_cscale. lia. Qed.
Lemma ev_lsub rho a b c : lsub a b = Some c -> ev rho a = ev rho b + ev rho c.
Proof.
  unfold lsub. destruct (N.leb_spec (lc b) (lc a)); [| discriminate].
  destruct (csub (lv a) (lv b)) eqn:Hs; intros H'; inversion H'; subst.
  apply (sumc_csub rho) in Hs. unfold ev; cbn. lia.
Qed.
Lemma ev_lsubc rho a k c : lsubc a k = Some c -> ev rho a = k + ev rho c.
Proof.
  unfold lsubc. destruct (N.leb_spec k (lc a)); [| discriminate].
  intros H'; inversion H'; subst. unfold ev; cbn. lia.
Qed.
Lemma ev_lle rho a b : lle a b = true -> ev rho a <= ev rho b.
Proof.
  unfold lle. destruct (lsub b a) eqn:H; [| discriminate]. intros _.
  apply (ev_lsub rho) in H. lia.
Qed.
Lemma ev_ldiv rho a d c : ldiv a d = Some c -> ev rho c = ev rho a / Npos d.
Proof.
  unfold ldiv. destruct (cdiv (lv a) d) eqn:Hc; [| discriminate].
  intros H'; inversion H'; subst. apply (sumc_cdiv rho) in Hc.
  unfold ev; cbn. rewrite Hc.
  rewrite (N.mul_comm (Npos d)), N.div_add by discriminate. lia.
Qed.
Lemma ev_lzero rho e : lzero e = true -> ev rho e = 0.
Proof. destruct e as [[| p] [| x l]]; cbn; try discriminate. reflexivity. Qed.

(** Variables of a form are all below a bound. *)
Definition vars_lt (b : N) (e : lin) : bool := forallb (fun '(v, _) => N.ltb v b) (lv e).

Lemma ev_vars_lt rho rho' b e :
  vars_lt b e = true -> (forall v, v < b -> rho' v = rho v) -> ev rho' e = ev rho e.
Proof.
  unfold vars_lt, ev. destruct e as [k l]; cbn. intros H Hr. f_equal.
  induction l as [| [v x] l IH]; cbn in *; [reflexivity |].
  apply andb_prop in H as [H1 H2]. apply N.ltb_lt in H1.
  rewrite Hr by exact H1. rewrite IH by exact H2. reflexivity.
Qed.

(** * Words, configurations, denotation *)

Definition word := list Sym.
Notation z0 := (@const Sym S0).
Definition blank : word := [S0; S0; S0; S0].

Definition seqb (a b : Sym) : bool :=
  match a, b with S0, S0 | S1, S1 => true | _, _ => false end.
Fixpoint weqb (a b : word) : bool :=
  match a, b with
  | [], [] => true
  | x :: a', y :: b' => seqb x y && weqb a' b'
  | _, _ => false
  end.
Lemma weqb_eq a b : weqb a b = true -> a = b.
Proof.
  revert b; induction a as [| x a IH]; intros [| y b] H; cbn in H; try discriminate; [reflexivity |].
  apply andb_prop in H as [H1 H2]. apply IH in H2. subst.
  destruct x, y; cbn in H1; try discriminate; reflexivity.
Qed.

Definition qeqb (a b : Q) : bool :=
  match a, b with
  | A, A | B, B | C, C | D, D | E, E | F, F => true
  | _, _ => false
  end.
Lemma qeqb_eq a b : qeqb a b = true -> a = b.
Proof. destruct a, b; cbn; congruence. Qed.
Definition deqb (a b : dir) : bool :=
  match a, b with L, L | R, R => true | _, _ => false end.
Lemma deqb_eq a b : deqb a b = true -> a = b.
Proof. destruct a, b; cbn; congruence. Qed.

Record conf (X : Type) := Cf { cq : Q; cd : dir; cl : list (word * X); cr : list (word * X) }.
Arguments Cf {X}. Arguments cq {X}. Arguments cd {X}. Arguments cl {X}. Arguments cr {X}.

Fixpoint flatR (s : list (word * N)) : list Sym :=
  match s with [] => [] | (w, n) :: s' => w ^^ N.to_nat n ++ flatR s' end.
Fixpoint flatL (s : list (word * N)) : list Sym :=
  match s with [] => [] | (w, n) :: s' => (rev w) ^^ N.to_nat n ++ flatL s' end.

Definition tp (c : conf N) : Q * tape :=
  match cd c with
  | R => (flatL (cl c) *> z0) {{cq c}}> (flatR (cr c) *> z0)
  | L => (flatL (cl c) *> z0) <{{cq c}} (flatR (cr c) *> z0)
  end.

Definition inst (rho : N -> N) (s : list (word * lin)) : list (word * N) :=
  map (fun '(w, e) => (w, ev rho e)) s.
Definition den (rho : N -> N) (c : conf lin) : Q * tape :=
  tp (Cf (cq c) (cd c) (inst rho (cl c)) (inst rho (cr c))).

Fixpoint seqeqb (a b : list (word * lin)) : bool :=
  match a, b with
  | [], [] => true
  | (w, e) :: a', (w', e') :: b' => weqb w w' && leqb e e' && seqeqb a' b'
  | _, _ => false
  end.
Lemma seqeqb_eq a b : seqeqb a b = true -> a = b.
Proof.
  revert b; induction a as [| [w e] a IH]; intros [| [w' e'] b] H; cbn in H; try discriminate; [reflexivity |].
  apply andb_prop in H as [H H3]. apply andb_prop in H as [H1 H2].
  apply weqb_eq in H1. apply leqb_eq in H2. apply IH in H3. subst. reflexivity.
Qed.
Definition confeqb (a b : conf lin) : bool :=
  qeqb (cq a) (cq b) && deqb (cd a) (cd b) && seqeqb (cl a) (cl b) && seqeqb (cr a) (cr b).
Lemma confeqb_eq a b : confeqb a b = true -> a = b.
Proof.
  destruct a, b; unfold confeqb; cbn. intros H.
  repeat match goal with H : _ && _ = true |- _ => apply andb_prop in H as [? ?] end.
  repeat match goal with
         | H : qeqb _ _ = true |- _ => apply qeqb_eq in H
         | H : deqb _ _ = true |- _ => apply deqb_eq in H
         | H : seqeqb _ _ = true |- _ => apply seqeqb_eq in H
         end. subst. reflexivity.
Qed.

(** * Stream facts *)

Lemma const0_unfold : @const Sym S0 = @Cons Sym S0 (@const Sym S0).
Proof. apply const_unfold. Qed.

Lemma blank_const : blank *> z0 = z0.
Proof. unfold blank. cbn [Str_app]. rewrite <- !const0_unfold. reflexivity. Qed.

Lemma blank_pow_const n : blank ^^ n *> z0 = z0.
Proof.
  induction n; [reflexivity |]. cbn [lpow]. rewrite Str_app_assoc, IHn. apply blank_const.
Qed.

Lemma pow_S_l (w : word) n X : w ^^ S n *> X = w *> w ^^ n *> X.
Proof. cbn [lpow]. apply Str_app_assoc. Qed.

Lemma pow_S_r (w : word) n X : w ^^ S n *> X = w ^^ n *> w *> X.
Proof. rewrite pow_S_l. symmetry. apply lpow_shift'. Qed.

Lemma pow_add (w : word) a b X : w ^^ (a + b) *> X = w ^^ a *> w ^^ b *> X.
Proof. rewrite lpow_add. apply Str_app_assoc. Qed.

(** * Block simulation *)

Fixpoint bsim (T : TM) (fuel : nat) (q : Q) (a : list Sym) (s : Sym) (b : list Sym)
  : option (Q * word * dir) :=
  match fuel with
  | O => None
  | S f =>
    match T (q, s) with
    | None => None
    | Some (s', R, q') =>
      match b with
      | [] => Some (q', rev (s' :: a), R)
      | x :: b' => bsim T f q' (s' :: a) x b'
      end
    | Some (s', L, q') =>
      match a with
      | [] => Some (q', s' :: b, L)
      | x :: a' => bsim T f q' a' x (s' :: b)
      end
    end
  end.

Definition bout (q : Q) (w : word) (d : dir) (l r : Stream Sym) : Q * tape :=
  match d with
  | R => (rev w *> l) {{q}}> r
  | L => l <{{q}} (w *> r)
  end.

Lemma bsim_spec T fuel q a s b q' w d :
  bsim T fuel q a s b = Some (q', w, d) ->
  forall l r, (q;; (a *> l) {{s}} (b *> r)) -[ T ]->+ bout q' w d l r.
Proof.
  revert q a s b. induction fuel as [| f IH]; intros q a s b H l r; [discriminate |].
  cbn in H. destruct (T (q, s)) as [[[s' []] q''] |] eqn:Ht; [| | discriminate].
  - destruct a as [| x a'].
    + inversion H; subst. apply progress_base. cbn.
      apply (step_left (l := l) (r := b *> r)) in Ht. exact Ht.
    + eapply progress_step.
      * apply (step_left (l := x >> a' *> l) (r := b *> r)) in Ht. exact Ht.
      * exact (IH _ _ _ _ H l r).
  - destruct b as [| x b'].
    + injection H as Hq Hw Hd; subst q' w d. apply progress_base. cbn [bout]. replace (rev (rev a ++ [s'])) with (s' :: a) by (rewrite rev_app_distr, rev_involutive; reflexivity).
      apply (step_right (l := a *> l) (r := r)) in Ht. exact Ht.
    + eapply progress_step.
      * apply (step_right (l := a *> l) (r := x >> b' *> r)) in Ht. exact Ht.
      * exact (IH _ _ _ _ H l r).
Qed.

Definition bfuel : nat := 64.

(** One block step on word [w] from state [q] facing [d]. *)
Definition bstep (T : TM) (q : Q) (d : dir) (w : word) : option (Q * word * dir) :=
  match d with
  | R => match w with [] => None | x :: w' => bsim T bfuel q [] x w' end
  | L => match rev w with [] => None | y :: ys => bsim T bfuel q ys y [] end
  end.

Definition bin (q : Q) (d : dir) (w : word) (l r : Stream Sym) : Q * tape :=
  match d with
  | R => l {{q}}> (w *> r)
  | L => (rev w *> l) <{{q}} r
  end.

Lemma bstep_spec T q d w q' w' d' :
  bstep T q d w = Some (q', w', d') ->
  forall l r, bin q d w l r -[ T ]->+ bout q' w' d' l r.
Proof.
  intros H l r. destruct d; cbn [bstep bin] in H |- *.
  - destruct (rev w) as [| y ys] eqn:Hw; [discriminate |].
    apply (bsim_spec _ _ _ _ _ _ _ _ _ H l r).
  - destruct w as [| x w0]; [discriminate |].
    apply (bsim_spec _ _ _ _ _ _ _ _ _ H l r).
Qed.

Lemma chain_R T q w w' :
  bstep T q R w = Some (q, w', R) ->
  forall n l r, l {{q}}> (w ^^ n *> r) -[ T ]->* ((rev w') ^^ n *> l) {{q}}> r.
Proof.
  intros H n. induction n as [| n IH]; intros l r; [apply evstep_refl |].
  rewrite pow_S_l. eapply evstep_trans.
  - apply progress_evstep. apply (bstep_spec _ _ _ _ _ _ _ H l (w ^^ n *> r)).
  - cbn [bout]. eapply evstep_trans; [apply IH |]. rewrite pow_S_r. apply evstep_refl.
Qed.

Lemma chain_L T q w w' :
  bstep T q L w = Some (q, w', L) ->
  forall n l r, ((rev w) ^^ n *> l) <{{q}} r -[ T ]->* l <{{q}} (w' ^^ n *> r).
Proof.
  intros H n. induction n as [| n IH]; intros l r; [apply evstep_refl |].
  rewrite pow_S_l. eapply evstep_trans.
  - apply progress_evstep. apply (bstep_spec _ _ _ _ _ _ _ H ((rev w) ^^ n *> l) r).
  - cbn [bout]. eapply evstep_trans; [apply IH |]. rewrite pow_S_r. apply evstep_refl.
Qed.

(** * Symbolic block moves *)

Definition push (w : word) (e : lin) (s : list (word * lin)) : list (word * lin) :=
  match s with
  | (w', e') :: s' => if weqb w w' then (w', ladd e' e) :: s' else (w, e) :: s
  | [] => if weqb w blank then [] else [(w, e)]
  end.

Definition pop1 (s : list (word * lin)) : option (word * list (word * lin)) :=
  match s with
  | [] => Some (blank, [])
  | (w, e) :: s' =>
    if 1 <=? lc e then
      let e' := LN (lc e - 1) (lv e) in Some (w, if lzero e' then s' else (w, e') :: s')
    else None
  end.

Definition nearw (s : list (word * lin)) : word :=
  match s with [] => blank | (w, _) :: _ => w end.

Definition one : lin := lconst 1.

Definition bmove (T : TM) (c : conf lin) : option (conf lin * bool) :=
  let q := cq c in
  let d := cd c in
  let near := match d with R => cr c | L => cl c end in
  let far := match d with R => cl c | L => cr c end in
  let mk q2 d2 nr fr := match d with R => Cf q2 d2 fr nr | L => Cf q2 d2 nr fr end in
  match bstep T q d (nearw near) with
  | None => None
  | Some (q2, w2, d2) =>
    if qeqb q2 q && deqb d2 d then
      match near with
      | [] => None
      | (w, e) :: near' => Some (mk q d near' (push w2 e far), false)
      end
    else
      match pop1 near with
      | None => None
      | Some (_, near') =>
        if deqb d2 d then Some (mk q2 d2 near' (push w2 one far), true)
        else Some (mk q2 d2 (push w2 one near') far, true)
      end
  end.

(* semantics of sides *)
Lemma flatR_inst_push rho w e s X :
  flatR (inst rho (push w e s)) *> X = w ^^ N.to_nat (ev rho e) *> flatR (inst rho s) *> X
  \/ (s = [] /\ w = blank).
Proof.
  destruct s as [| [w' e'] s'].
  - cbn. destruct (weqb w blank) eqn:Hb; [right; split; [reflexivity | apply weqb_eq; exact Hb] |].
    left. cbn. rewrite Str_app_assoc. reflexivity.
  - left. cbn. destruct (weqb w w') eqn:Hw.
    + apply weqb_eq in Hw. subst w'. cbn [inst map flatR flatL].
      rewrite ev_ladd, N2Nat.inj_add, !Str_app_assoc, <- !pow_add.
      rewrite (Nat.add_comm (N.to_nat (ev rho e'))). reflexivity.
    + cbn. rewrite Str_app_assoc. reflexivity.
Qed.

Lemma flatR_push rho w e s :
  flatR (inst rho (push w e s)) *> z0 = w ^^ N.to_nat (ev rho e) *> flatR (inst rho s) *> z0.
Proof.
  destruct (flatR_inst_push rho w e s (z0)) as [H | [-> ->]]; [exact H |].
  cbn. rewrite blank_pow_const. reflexivity.
Qed.

Lemma flatL_push rho w e s :
  flatL (inst rho (push w e s)) *> z0 = (rev w) ^^ N.to_nat (ev rho e) *> flatL (inst rho s) *> z0.
Proof.
  destruct s as [| [w' e'] s'].
  - cbn. destruct (weqb w blank) eqn:Hb.
    + apply weqb_eq in Hb. subst w. cbn [flatL inst map]. cbn [Str_app].
      change (rev blank) with blank. rewrite blank_pow_const. reflexivity.
    + cbn. rewrite Str_app_assoc. reflexivity.
  - cbn. destruct (weqb w w') eqn:Hw.
    + apply weqb_eq in Hw. subst w'. cbn [inst map flatR flatL].
      rewrite ev_ladd, N2Nat.inj_add, !Str_app_assoc, <- !pow_add.
      rewrite (Nat.add_comm (N.to_nat (ev rho e'))). reflexivity.
    + cbn. rewrite Str_app_assoc. reflexivity.
Qed.

Lemma pop1_R rho s w s' :
  pop1 s = Some (w, s') -> w = nearw s /\
  flatR (inst rho s) *> z0 = w *> flatR (inst rho s') *> z0.
Proof.
  destruct s as [| [w0 e] s0]; cbn [pop1 nearw]; intros H.
  - injection H as <- <-. split; [reflexivity |].
    change (flatR (inst rho [])) with (@nil Sym). cbn [Str_app]. symmetry. apply blank_const.
  - destruct (N.leb_spec 1 (lc e)); [| discriminate].
    assert (He : N.to_nat (ev rho e) = S (N.to_nat (ev rho (LN (lc e - 1) (lv e))))).
    { unfold ev; cbn [lc lv]. lia. }
    destruct (lzero (LN (lc e - 1) (lv e))) eqn:Hz; injection H as <- <-; split; try reflexivity;
      cbn [inst map flatR]; rewrite Str_app_assoc, He, pow_S_l.
    + apply (ev_lzero rho) in Hz. rewrite Hz. reflexivity.
    + cbn [inst map flatR]. rewrite Str_app_assoc. reflexivity.
Qed.

Lemma pop1_L rho s w s' :
  pop1 s = Some (w, s') -> w = nearw s /\
  flatL (inst rho s) *> z0 = rev w *> flatL (inst rho s') *> z0.
Proof.
  destruct s as [| [w0 e] s0]; cbn [pop1 nearw]; intros H.
  - injection H as <- <-. split; [reflexivity |].
    change (flatL (inst rho [])) with (@nil Sym). cbn [Str_app]. symmetry. apply blank_const.
  - destruct (N.leb_spec 1 (lc e)); [| discriminate].
    assert (He : N.to_nat (ev rho e) = S (N.to_nat (ev rho (LN (lc e - 1) (lv e))))).
    { unfold ev; cbn [lc lv]. lia. }
    destruct (lzero (LN (lc e - 1) (lv e))) eqn:Hz; injection H as <- <-; split; try reflexivity;
      cbn [inst map flatL]; rewrite Str_app_assoc, He, pow_S_l.
    + apply (ev_lzero rho) in Hz. rewrite Hz. reflexivity.
    + cbn [inst map flatL]. rewrite Str_app_assoc. reflexivity.
Qed.

Lemma ev_one rho : N.to_nat (ev rho one) = 1%nat.
Proof. reflexivity. Qed.

Lemma pow1 (w : word) X : w ^^ 1 *> X = w *> X.
Proof. cbn. rewrite app_nil_r. reflexivity. Qed.

Lemma bmove_spec T c c' p :
  bmove T c = Some (c', p) -> forall rho,
  den rho c -[ T ]->* den rho c' /\ (p = true -> den rho c -[ T ]->+ den rho c').
Proof.
  destruct c as [q d cl0 cr0]. unfold bmove; cbn [cq cd cl cr].
  intros H rho.
  destruct (bstep T q d (nearw (match d with R => cr0 | L => cl0 end))) as [[[q2 w2] d2] |] eqn:Hb;
    [| discriminate].
  destruct (qeqb q2 q && deqb d2 d) eqn:Hc.
  - apply andb_prop in Hc as [Hq Hd]. apply qeqb_eq in Hq. apply deqb_eq in Hd. subst q2 d2.
    destruct d.
    + destruct cl0 as [| [w e] near']; [discriminate |]. inversion H; subst c' p. split; [| discriminate].
      unfold den, tp; cbn [cq cd cl cr]. cbn [nearw] in Hb.
      rewrite flatR_push. cbn [inst map flatL]. rewrite Str_app_assoc.
      apply (chain_L _ _ _ _ Hb).
    + destruct cr0 as [| [w e] near']; [discriminate |]. inversion H; subst c' p. split; [| discriminate].
      unfold den, tp; cbn [cq cd cl cr]. cbn [nearw] in Hb.
      rewrite flatL_push. cbn [inst map flatR]. rewrite Str_app_assoc.
      apply (chain_R _ _ _ _ Hb).
  - destruct d.
    + destruct (pop1 cl0) as [[w near'] |] eqn:Hp; [| discriminate].
      destruct (pop1_L rho _ _ _ Hp) as [Hw Hs]. subst w.
      assert (Hst : den rho (Cf q L cl0 cr0) -[ T ]->+ bout q2 w2 d2 (flatL (inst rho near') *> z0) (flatR (inst rho cr0) *> z0)).
      { unfold den, tp; cbn [cq cd cl cr]. rewrite Hs. apply (bstep_spec _ _ _ _ _ _ _ Hb). }
      destruct d2; cbn [deqb] in H; inversion H; subst c' p;
        unfold den, tp in Hst |- *; cbn [cq cd cl cr bout] in Hst |- *;
        rewrite ?flatR_push, ?flatL_push, ?ev_one, ?pow1;
        (split; [apply progress_evstep; exact Hst | intros _; exact Hst]).
    + destruct (pop1 cr0) as [[w near'] |] eqn:Hp; [| discriminate].
      destruct (pop1_R rho _ _ _ Hp) as [Hw Hs]. subst w.
      assert (Hst : den rho (Cf q R cl0 cr0) -[ T ]->+ bout q2 w2 d2 (flatL (inst rho cl0) *> z0) (flatR (inst rho near') *> z0)).
      { unfold den, tp; cbn [cq cd cl cr]. rewrite Hs. apply (bstep_spec _ _ _ _ _ _ _ Hb). }
      destruct d2; cbn [deqb] in H; inversion H; subst c' p;
        unfold den, tp in Hst |- *; cbn [cq cd cl cr bout] in Hst |- *;
        rewrite ?flatR_push, ?flatL_push, ?ev_one, ?pow1;
        (split; [apply progress_evstep; exact Hst | intros _; exact Hst]).
Qed.

(** * Zero-block cleanup after a rule application (mirrors engine.py fix_zero) *)

(* far-first processing; [acc] is the processed prefix, reversed *)
Fixpoint fz (acc rest : list (word * lin)) : list (word * lin) :=
  match rest with
  | [] => rev acc
  | (w, e) :: rest' =>
    if lzero e then
      match acc, rest' with
      | (w1, e1) :: acc', (w2, e2) :: rest'' =>
        if weqb w1 w2 then fz ((w1, ladd e1 e2) :: acc') rest'' else fz acc rest'
      | _, _ => fz acc rest'
      end
    else fz ((w, e) :: acc) rest'
  end.

Fixpoint strip (ff : list (word * lin)) : list (word * lin) :=
  match ff with
  | (w, e) :: ff' => if weqb w blank then strip ff' else ff
  | [] => []
  end.

Definition fzside (nf : list (word * lin)) : list (word * lin) := rev (strip (fz [] (rev nf))).

Section FlatG.
  Variable g : word -> N -> list Sym.
  Variable g0 : forall w, g w 0 = [].
  Variable gadd : forall w a b, g w (a + b) = g w a ++ g w b.
  Variable gblank : forall n, g blank n *> z0 = z0.

  Fixpoint flatG (s : list (word * N)) : list Sym :=
    match s with [] => [] | (w, n) :: s' => g w n ++ flatG s' end.

  Lemma flatG_app a b : flatG (a ++ b) = flatG a ++ flatG b.
  Proof. induction a as [| [w n] a IH]; cbn; [reflexivity |]. rewrite IH, app_assoc. reflexivity. Qed.

  Lemma gcomm w a b : g w a ++ g w b = g w b ++ g w a.
  Proof. rewrite <- !gadd, N.add_comm. reflexivity. Qed.

  Lemma fz_spec_n rho n : forall rest acc, (length rest <= n)%nat ->
    flatG (inst rho (rev (fz acc rest))) = flatG (inst rho (rev rest ++ acc)).
  Proof.
    induction n as [| n IH]; intros rest acc Hn.
    - destruct rest; [| cbn in Hn; lia]. cbn [fz rev app]. rewrite rev_involutive. reflexivity.
    - destruct rest as [| [w e] rest]; [cbn [fz rev app]; rewrite rev_involutive; reflexivity |].
      cbn [length] in Hn. cbn [fz]. destruct (lzero e) eqn:Hz.
      + apply (ev_lzero rho) in Hz.
        destruct acc as [| [w1 e1] acc'].
        * rewrite IH by lia. cbn [rev]. rewrite <- app_assoc. unfold inst. rewrite !map_app, !flatG_app.
          cbn. rewrite Hz, g0. cbn [app]. rewrite ?app_nil_r, <- ?app_assoc. reflexivity.
        * destruct rest as [| [w2 e2] rest''].
          -- rewrite IH by (cbn; lia). cbn [rev]. rewrite <- app_assoc. unfold inst. rewrite !map_app, !flatG_app.
             cbn. rewrite Hz, g0. cbn [app]. rewrite ?app_nil_r, <- ?app_assoc. reflexivity.
          -- cbn [length] in Hn. destruct (weqb w1 w2) eqn:Hw.
             ++ apply weqb_eq in Hw. subst w2.
                rewrite IH by lia. cbn [rev]. rewrite <- !app_assoc. unfold inst. rewrite !map_app, !flatG_app.
                cbn. rewrite Hz, g0, ev_ladd, gadd. cbn. rewrite !app_assoc. f_equal.
                rewrite <- !app_assoc. f_equal. apply gcomm.
             ++ rewrite IH by (cbn; lia). cbn [rev]. rewrite <- app_assoc. unfold inst. rewrite !map_app, !flatG_app.
                cbn. rewrite Hz, g0. cbn [app]. rewrite ?app_nil_r, <- ?app_assoc. reflexivity.
      + rewrite IH by lia. cbn [rev]. rewrite <- app_assoc. reflexivity.
  Qed.

  Lemma fz_spec rho acc rest :
    flatG (inst rho (rev (fz acc rest))) = flatG (inst rho (rev rest ++ acc)).
  Proof. apply (fz_spec_n rho (length rest)). lia. Qed.


  Lemma strip_spec rho ff :
    flatG (inst rho (rev (strip ff))) *> z0 = flatG (inst rho (rev ff)) *> z0.
  Proof.
    induction ff as [| [w e] ff IH]; cbn [strip]; [reflexivity |].
    destruct (weqb w blank) eqn:Hw; [| reflexivity].
    apply weqb_eq in Hw. subst w. rewrite IH. cbn [rev]. unfold inst. rewrite map_app, flatG_app.
    rewrite Str_app_assoc. cbn [map flatG]. rewrite app_nil_r, gblank. reflexivity.
  Qed.

  Lemma fzside_spec rho nf :
    flatG (inst rho (fzside nf)) *> z0 = flatG (inst rho nf) *> z0.
  Proof.
    unfold fzside. rewrite strip_spec. rewrite fz_spec, app_nil_r, rev_involutive. reflexivity.
  Qed.
End FlatG.

Lemma flatR_G s : flatR s = flatG (fun w n => w ^^ N.to_nat n) s.
Proof. induction s as [| [w n] s IH]; cbn; [reflexivity |]. rewrite IH. reflexivity. Qed.
Lemma flatL_G s : flatL s = flatG (fun w n => (rev w) ^^ N.to_nat n) s.
Proof. induction s as [| [w n] s IH]; cbn; [reflexivity |]. rewrite IH. reflexivity. Qed.

Lemma fzside_R rho nf : flatR (inst rho (fzside nf)) *> z0 = flatR (inst rho nf) *> z0.
Proof.
  rewrite !flatR_G. apply fzside_spec.
  - reflexivity.
  - intros w a b. rewrite N2Nat.inj_add. apply lpow_add.
  - intros n. apply blank_pow_const.
Qed.
Lemma fzside_L rho nf : flatL (inst rho (fzside nf)) *> z0 = flatL (inst rho nf) *> z0.
Proof.
  rewrite !flatL_G. apply fzside_spec.
  - reflexivity.
  - intros w a b. rewrite N2Nat.inj_add. apply lpow_add.
  - intros n. apply blank_pow_const.
Qed.

(** * Diff rules, built from the configuration they are proved at *)

Inductive slot := SFix (e : lin) | SGen (k : N) (neg : bool) (mag : N).
Inductive dl := DP (p : N) (m : positive) | DN (p : N) (m : positive).

Fixpoint dlook (p : N) (ds : list dl) : option (bool * positive) :=
  match ds with
  | [] => None
  | DP q m :: ds' => if N.eqb p q then Some (false, m) else dlook p ds'
  | DN q m :: ds' => if N.eqb p q then Some (true, m) else dlook p ds'
  end.

(* engine.py prove_rule: k = max(1, -delta) + extra for a moving slot, 1 + extra for a
   generalized constant slot; a constant slot is fixed unless [gf] *)
Definition mkslot (gf : bool) (extra : N) (d : option (bool * positive)) (x : lin) : slot :=
  match d with
  | None => if gf then SGen (1 + extra) false 0 else SFix x
  | Some (false, m) => SGen (1 + extra) false (Npos m)
  | Some (true, m) => SGen (Npos m + extra) true (Npos m)
  end.

Fixpoint mkslots gf extra ds (p : N) (xs : list (word * lin)) : list slot :=
  match xs with
  | [] => []
  | (_, x) :: xs' => mkslot gf extra (dlook p ds) x :: mkslots gf extra ds (N.succ p) xs'
  end.

Definition gv (base p : N) (k : N) : lin := LN k [(base + p, 1%positive)].
Definition slhs base p s := match s with SFix e => e | SGen k _ _ => gv base p k end.
Definition srhs base p s :=
  match s with SFix e => e | SGen k neg mag => gv base p (if neg then k - mag else k + mag) end.

Fixpoint side_map (f : N -> slot -> lin) (p : N) (sl : list slot) (xs : list (word * lin)) : list (word * lin) :=
  match sl, xs with
  | s :: sl', (w, _) :: xs' => (w, f p s) :: side_map f (N.succ p) sl' xs'
  | _, _ => []
  end.

Definition lhs base c sl sr : conf lin :=
  Cf (cq c) (cd c) (side_map (slhs base) 0 sl (cl c)) (side_map (slhs base) 500 sr (cr c)).
Definition rhs base c sl sr : conf lin :=
  Cf (cq c) (cd c) (side_map (srhs base) 0 sl (cl c)) (side_map (srhs base) 500 sr (cr c)).

Definition wf_slot base s :=
  match s with
  | SFix e => vars_lt base e
  | SGen k neg mag => if neg then (1 <=? mag) && (mag <=? k) else true
  end.
Definition wf_rule base (c : conf lin) sl sr :=
  forallb (wf_slot base) sl && forallb (wf_slot base) sr &&
  (N.of_nat (length (cl c)) <? 500) && (N.of_nat (length sl) =? N.of_nat (length (cl c))) &&
  (N.of_nat (length sr) =? N.of_nat (length (cr c))).

(* values *)
Fixpoint fillw (xs : list (word * lin)) (vs : list N) : list (word * N) :=
  match xs, vs with
  | (w, _) :: xs', v :: vs' => (w, v) :: fillw xs' vs'
  | _, _ => []
  end.

Definition sstepn (n : nat) (s : slot) (v : N) : N :=
  match s with
  | SFix _ => v
  | SGen _ neg mag => if neg then v - N.of_nat n * mag else v + N.of_nat n * mag
  end.

Fixpoint vmap (f : slot -> N -> N) (sl : list slot) (vs : list N) : list N :=
  match sl, vs with
  | s :: sl', v :: vs' => f s v :: vmap f sl' vs'
  | _, _ => []
  end.

Definition sokj (rho : N -> N) (j : nat) (s : slot) (v : N) : Prop :=
  match s with
  | SFix e => v = ev rho e
  | SGen k neg mag => k <= v /\ (neg = true -> k + N.of_nat j * mag <= v /\ mag <= k)
  end.

Definition fillc (c : conf lin) (vl vr : list N) : conf N :=
  Cf (cq c) (cd c) (fillw (cl c) vl) (fillw (cr c) vr).

Definition RuleV (T : TM) (c : conf lin) (sl sr : list slot) : Prop :=
  forall rho vl vr, Forall2 (sokj rho 0) sl vl -> Forall2 (sokj rho 0) sr vr ->
  tp (fillc c vl vr) -[ T ]->* tp (fillc c (vmap (sstepn 1) sl vl) (vmap (sstepn 1) sr vr)).

Lemma sokj_step rho j s v : sokj rho (S j) s v -> sokj rho j s (sstepn 1 s v).
Proof.
  destruct s as [e | k [] mag]; cbn [sokj sstepn]; [auto | |].
  - rewrite Nat2N.inj_succ. intros [H1 H2]. specialize (H2 eq_refl). split; [nia | intros _; nia].
  - intros [H1 H2]. split; [nia | discriminate].
Qed.

Lemma sokj_0 rho j s v : sokj rho j s v -> sokj rho 0 s v.
Proof. destruct s as [e | k [] mag]; cbn; [auto | |]; intros [H1 H2]; split; auto; intros E; specialize (H2 E); lia. Qed.

Lemma vmap_step sl vl j : vmap (sstepn (S j)) sl (vmap (sstepn 1) sl vl) = vmap (sstepn (S (S j))) sl vl.
Proof.
  revert vl; induction sl as [| s sl IH]; intros [| v vl]; cbn; try reflexivity.
  rewrite IH. f_equal. destruct s as [e | k [] mag]; cbn [sstepn]; rewrite ?Nat2N.inj_succ; [reflexivity | nia | nia].
Qed.

Lemma Forall2_vmap_step rho j sl vl :
  Forall2 (sokj rho (S j)) sl vl -> Forall2 (sokj rho j) sl (vmap (sstepn 1) sl vl).
Proof. induction 1; cbn; constructor; [apply sokj_step |]; assumption. Qed.

Lemma Forall2_sokj_0 rho j sl vl : Forall2 (sokj rho j) sl vl -> Forall2 (sokj rho 0) sl vl.
Proof. induction 1; constructor; [eapply sokj_0; eassumption | assumption]. Qed.

Lemma iterV T c sl sr : RuleV T c sl sr ->
  forall j rho vl vr, Forall2 (sokj rho j) sl vl -> Forall2 (sokj rho j) sr vr ->
  tp (fillc c vl vr) -[ T ]->* tp (fillc c (vmap (sstepn (S j)) sl vl) (vmap (sstepn (S j)) sr vr)).
Proof.
  intros HR j. unfold RuleV in HR. induction j as [| j IH]; intros rho vl vr Hl Hr.
  - exact (HR rho vl vr Hl Hr).
  - eapply evstep_trans.
    + apply (HR rho); eapply Forall2_sokj_0; eassumption.
    + rewrite <- !vmap_step. apply (IH rho); apply Forall2_vmap_step; assumption.
Qed.

(* valuation extension for the generalized slots *)
Definition gwv (s : slot) (v : N) : N := match s with SGen k _ _ => v - k | SFix _ => 0 end.

Definition ext (rho : N -> N) (base : N) (wl wr : list N) (v : N) : N :=
  if v <? base then rho v
  else let p := v - base in
       if p <? 500 then nth (N.to_nat p) wl 0 else nth (N.to_nat (p - 500)) wr 0.

Lemma side_map_inst rho rho' base p sl xs vs :
  Forall2 (sokj rho 0) sl vs ->
  length sl = length xs ->
  forallb (wf_slot base) sl = true ->
  (forall v, v < base -> rho' v = rho v) ->
  (forall i, (i < length sl)%nat -> rho' (base + p + N.of_nat i) = nth i (vmap gwv sl vs) 0) ->
  inst rho' (side_map (slhs base) p sl xs) = fillw xs vs /\
  inst rho' (side_map (srhs base) p sl xs) = fillw xs (vmap (sstepn 1) sl vs).
Proof.
  intros H. revert p xs. induction H as [| s v sl vs Hs H IH]; intros p xs Hlen Hwf Hlow Hpos.
  - destruct xs; [| discriminate]. split; reflexivity.
  - destruct xs as [| [w x] xs]; [discriminate |]. cbn in Hlen. injection Hlen as Hlen.
    cbn [forallb] in Hwf. apply andb_prop in Hwf as [Hw1 Hw2].
    destruct (IH (N.succ p) xs Hlen Hw2 Hlow) as [IH1 IH2].
    { intros i Hi. specialize (Hpos (S i)). cbn [length nth vmap] in Hpos.
      rewrite <- Hpos by lia. f_equal. lia. }
    specialize (Hpos 0%nat). cbn [length nth vmap] in Hpos. rewrite N.add_0_r in Hpos.
    specialize (Hpos ltac:(lia)).
    cbn [side_map inst map fillw vmap]. unfold inst in IH1, IH2. rewrite IH1, IH2.
    destruct s as [e | k neg mag]; cbn [sokj slhs srhs gwv nth] in Hs, Hpos |- *.
    + subst v. rewrite (ev_vars_lt rho rho' base e Hw1 Hlow). split; reflexivity.
    + destruct Hs as [Hk Hn]. unfold gv, ev; cbn [lc lv sumc]. rewrite Hpos.
      destruct neg; cbn [wf_slot sstepn] in Hw1 |- *.
      * apply andb_prop in Hw1 as [_ Hm]. apply N.leb_le in Hm.
        split; f_equal; f_equal; lia.
      * split; f_equal; f_equal; lia.
Qed.

Lemma ruleV_of_run T base c sl sr :
  wf_rule base c sl sr = true ->
  (forall rho, den rho (lhs base c sl sr) -[ T ]->* den rho (rhs base c sl sr)) ->
  RuleV T c sl sr.
Proof.
  unfold wf_rule. intros Hwf Hrun rho vl vr Hl Hr.
  repeat match goal with H : _ && _ = true |- _ => apply andb_prop in H as [? ?] end.
  rename H into Hwl. 
  repeat match goal with
         | H : (_ =? _) = true |- _ => apply N.eqb_eq in H
         | H : (_ <? _) = true |- _ => apply N.ltb_lt in H
         end.
  set (rho' := ext rho base (vmap gwv sl vl) (vmap gwv sr vr)).
  assert (Hlow : forall v, v < base -> rho' v = rho v).
  { intros v Hv. unfold rho', ext. destruct (N.ltb_spec v base); [reflexivity | lia]. }
  assert (HlenL : length sl = length (cl c)) by lia.
  assert (HlenR : length sr = length (cr c)) by lia.
  destruct (side_map_inst rho rho' base 0 sl (cl c) vl Hl HlenL ltac:(assumption) Hlow) as [HL1 HL2].
  { intros i Hi. unfold rho', ext. destruct (N.ltb_spec (base + 0 + N.of_nat i) base); [lia |].
    destruct (N.ltb_spec (base + 0 + N.of_nat i - base) 500); [| lia].
    f_equal. lia. }
  destruct (side_map_inst rho rho' base 500 sr (cr c) vr Hr HlenR ltac:(assumption) Hlow) as [HR1 HR2].
  { intros i Hi. unfold rho', ext. destruct (N.ltb_spec (base + 500 + N.of_nat i) base); [lia |].
    destruct (N.ltb_spec (base + 500 + N.of_nat i - base) 500); [lia |].
    f_equal. lia. }
  specialize (Hrun rho'). unfold den, lhs, rhs in Hrun; cbn [cq cd cl cr] in Hrun.
  rewrite HL1, HL2, HR1, HR2 in Hrun. exact Hrun.
Qed.

(** * Applying a rule as many times as engine.py does *)

Definition cmin (c : lin) (acc : option lin) : option (option lin) :=
  match acc with
  | None => Some (Some c)
  | Some n0 => if lle c n0 then Some (Some c) else if lle n0 c then Some (Some n0) else None
  end.

Fixpoint cnt_side (sl : list slot) (xs : list (word * lin)) (acc : option lin) : option (option lin) :=
  match sl, xs with
  | [], [] => Some acc
  | s :: sl', (_, x) :: xs' =>
    match s with
    | SGen k true (Npos m) =>
      match lsubc x k with
      | None => None
      | Some y =>
        match ldiv y m with
        | None => None
        | Some q => match cmin (ladd q (lconst 1)) acc with None => None | Some acc' => cnt_side sl' xs' acc' end
        end
      end
    | SGen _ true 0 => None
    | _ => cnt_side sl' xs' acc
    end
  | _, _ => None
  end.

Definition cnt_ok (rho : N -> N) (n : N) (s : slot) (wx : word * lin) : Prop :=
  match s with
  | SGen k true mag => n <= (ev rho (snd wx) - k) / mag + 1
  | _ => True
  end.

Lemma cnt_side_spec rho sl xs acc res :
  cnt_side sl xs acc = Some res ->
  (forall a, acc = Some a -> 1 <= ev rho a) ->
  (forall n, res = Some n -> 1 <= ev rho n) /\
  (forall a, acc = Some a -> exists n, res = Some n /\ ev rho n <= ev rho a) /\
  (forall m, (forall n, res = Some n -> m <= ev rho n) -> Forall2 (cnt_ok rho m) sl xs).
Proof.
  revert xs acc. induction sl as [| s sl IH]; intros xs acc H Hacc.
  - destruct xs; [| discriminate]. injection H as <-.
    split; [exact Hacc |]. split; [intros a -> ; exists a; split; [reflexivity | lia] |].
    intros; constructor.
  - destruct xs as [| [w x] xs]; [discriminate |]. cbn [cnt_side] in H.
    destruct s as [e | k [] [| mg]].
    + destruct (IH _ _ H Hacc) as [H1 [H2 H3]]. split; [exact H1 |]. split; [exact H2 |].
      intros m Hm. constructor; [exact I | apply H3; exact Hm].
    + discriminate.
    + destruct (lsubc x k) as [y |] eqn:Hy; [| discriminate].
      destruct (ldiv y mg) as [q |] eqn:Hq; [| discriminate].
      destruct (cmin (ladd q (lconst 1)) acc) as [acc' |] eqn:Hc; [| discriminate].
      assert (Hcnt : ev rho (ladd q (lconst 1)) = (ev rho x - k) / Npos mg + 1).
      { rewrite ev_ladd, ev_lconst, (ev_ldiv rho _ _ _ Hq). apply (ev_lsubc rho) in Hy. f_equal. f_equal. lia. }
      assert (Hacc' : forall a, acc' = Some a -> 1 <= ev rho a /\ ev rho a <= ev rho (ladd q (lconst 1)) /\
                                (forall b, acc = Some b -> ev rho a <= ev rho b)).
      { intros a Ha. unfold cmin in Hc. destruct acc as [n0 |].
        - destruct (lle (ladd q (lconst 1)) n0) eqn:L1.
          + injection Hc as <-. injection Ha as <-. apply (ev_lle rho) in L1.
            split; [rewrite Hcnt; lia | split; [lia | intros b Hb; injection Hb as <-; lia]].
          + destruct (lle n0 (ladd q (lconst 1))) eqn:L2; [| discriminate].
            injection Hc as <-. injection Ha as <-. apply (ev_lle rho) in L2.
            split; [apply Hacc; reflexivity | split; [lia | intros b Hb; injection Hb as <-; lia]].
        - injection Hc as <-. injection Ha as <-. split; [rewrite Hcnt; lia | split; [lia | discriminate]]. }
      destruct (IH _ _ H (fun a Ha => proj1 (Hacc' a Ha))) as [H1 [H2 H3]].
      assert (Hsome : exists a, acc' = Some a).
      { unfold cmin in Hc. destruct acc as [n0 |].
        - destruct (lle (ladd q (lconst 1)) n0); [injection Hc as <-; eauto |].
          destruct (lle n0 (ladd q (lconst 1))); [injection Hc as <-; eauto | discriminate].
        - injection Hc as <-; eauto. }
      destruct Hsome as [a Ha]. destruct (H2 a Ha) as [n [Hn Hna]].
      destruct (Hacc' a Ha) as [Ha1 [Ha2 Ha3]].
      split; [exact H1 |]. split.
      * intros b Hb. exists n. split; [exact Hn |]. specialize (Ha3 b Hb). lia.
      * intros m Hm. constructor; [| apply H3; exact Hm].
        cbn [cnt_ok snd]. specialize (Hm n Hn). lia.
    + destruct (IH _ _ H Hacc) as [H1 [H2 H3]]. split; [exact H1 |]. split; [exact H2 |].
      intros m Hm. constructor; [exact I | apply H3; exact Hm].
    + destruct (IH _ _ H Hacc) as [H1 [H2 H3]]. split; [exact H1 |]. split; [exact H2 |].
      intros m Hm. constructor; [exact I | apply H3; exact Hm].
Qed.

Fixpoint new_side (sl : list slot) (xs : list (word * lin)) (n : lin) : option (list (word * lin)) :=
  match sl, xs with
  | [], [] => Some []
  | s :: sl', (w, x) :: xs' =>
    match new_side sl' xs' n with
    | None => None
    | Some t =>
      match s with
      | SFix _ => Some ((w, x) :: t)
      | SGen k neg mag =>
        if k <=? lc x then
          if neg then match lsub x (lscale n mag) with Some y => Some ((w, y) :: t) | None => None end
          else Some ((w, ladd x (lscale n mag)) :: t)
        else None
      end
    end
  | _, _ => None
  end.

Definition vals (rho : N -> N) (xs : list (word * lin)) : list N := map (fun '(_, x) => ev rho x) xs.

Definition fixeq (s : slot) (wx : word * lin) : Prop :=
  match s with SFix e => e = snd wx | _ => True end.

Lemma inst_fillw rho xs : inst rho xs = fillw xs (vals rho xs).
Proof. unfold inst, vals. induction xs as [| [w x] xs IH]; cbn; [reflexivity |]. f_equal. exact IH. Qed.

Lemma new_side_spec rho base n sl xs ys :
  new_side sl xs n = Some ys ->
  forallb (wf_slot base) sl = true ->
  Forall2 fixeq sl xs ->
  Forall2 (cnt_ok rho (ev rho n)) sl xs ->
  1 <= ev rho n ->
  Forall2 (sokj rho (pred (N.to_nat (ev rho n)))) sl (vals rho xs) /\
  inst rho ys = fillw xs (vmap (sstepn (N.to_nat (ev rho n))) sl (vals rho xs)).
Proof.
  intros H Hwf Hfx Hcn Hn1. revert ys H Hwf. induction Hfx as [| s [w x] sl xs Hf Hfx IH];
    intros ys H Hwf; inversion Hcn as [| ? ? ? ? Hc Hcn']; subst.
  - destruct ys; [| discriminate]. split; constructor.
  - cbn [new_side] in H. destruct (new_side sl xs n) as [t |] eqn:Ht; [| discriminate].
    cbn [forallb] in Hwf. apply andb_prop in Hwf as [Hw1 Hw2].
    destruct (IH Hcn' t eq_refl Hw2) as [IH1 IH2].
    destruct s as [e | k neg mag].
    + cbn in Hf. subst e. injection H as <-. split.
      * constructor; [reflexivity | exact IH1].
      * cbn. f_equal. exact IH2.
    + destruct (N.leb_spec k (lc x)) as [Hk |]; [| discriminate].
      assert (Hkx : k <= ev rho x) by (unfold ev; lia).
      set (Nn := ev rho n) in *.
      assert (HNn : N.of_nat (N.to_nat Nn) = Nn) by apply N2Nat.id.
      assert (HNp : N.of_nat (pred (N.to_nat Nn)) = Nn - 1) by lia.
      destruct neg.
      * destruct (lsub x (lscale n mag)) as [y |] eqn:Hy; [| discriminate].
        injection H as <-. apply (ev_lsub rho) in Hy. rewrite ev_lscale in Hy. fold Nn in Hy.
        cbn [wf_slot] in Hw1. apply andb_prop in Hw1 as [Hm1 Hm2].
        apply N.leb_le in Hm1. apply N.leb_le in Hm2.
        cbn [cnt_ok snd] in Hc.
        split.
        -- constructor; [| exact IH1]. cbn [sokj]. split; [exact Hkx |]. intros _. split; [| exact Hm2].
           rewrite HNp.
           assert (Hd : mag * ((ev rho x - k) / mag) <= ev rho x - k) by (apply N.Div0.mul_div_le; lia).
           nia.
        -- cbn [inst map vals vmap fillw sstepn]. f_equal; [| exact IH2]. f_equal. rewrite HNn. lia.
      * injection H as <-. split.
        -- constructor; [| exact IH1]. cbn [sokj]. split; [exact Hkx | discriminate].
        -- cbn [inst map vals vmap fillw sstepn]. f_equal; [| exact IH2]. f_equal.
           rewrite ev_ladd, ev_lscale, HNn. reflexivity.
Qed.

Definition apply (c : conf lin) (sl sr : list slot) : option (conf lin) :=
  match cnt_side sl (cl c) None with
  | None => None
  | Some a1 =>
    match cnt_side sr (cr c) a1 with
    | Some (Some n) =>
      match new_side sl (cl c) n, new_side sr (cr c) n with
      | Some yl, Some yr => Some (Cf (cq c) (cd c) (fzside yl) (fzside yr))
      | _, _ => None
      end
    | _ => None
    end
  end.

Lemma den_fz rho q d yl yr : den rho (Cf q d (fzside yl) (fzside yr)) = den rho (Cf q d yl yr).
Proof. unfold den, tp; cbn [cq cd cl cr]. rewrite fzside_R, fzside_L. reflexivity. Qed.

Lemma apply_spec T base c sl sr c' :
  RuleV T c sl sr ->
  forallb (wf_slot base) sl = true -> forallb (wf_slot base) sr = true ->
  Forall2 fixeq sl (cl c) -> Forall2 fixeq sr (cr c) ->
  apply c sl sr = Some c' ->
  forall rho, den rho c -[ T ]->* den rho c'.
Proof.
  intros HR Hwl Hwr Hfl Hfr H rho. unfold apply in H.
  destruct (cnt_side sl (cl c) None) as [a1 |] eqn:H1; [| discriminate].
  destruct (cnt_side sr (cr c) a1) as [[n |] |] eqn:H2; try discriminate.
  destruct (new_side sl (cl c) n) as [yl |] eqn:H3; [| discriminate].
  destruct (new_side sr (cr c) n) as [yr |] eqn:H4; [| discriminate].
  injection H as <-. rewrite den_fz.
  destruct (cnt_side_spec rho _ _ _ _ H1 ltac:(discriminate)) as [A1 [_ A3]].
  destruct (cnt_side_spec rho _ _ _ _ H2 A1) as [B1 [B2 B3]].
  assert (Hn1 : 1 <= ev rho n) by (apply B1; reflexivity).
  assert (CR : Forall2 (cnt_ok rho (ev rho n)) sr (cr c)).
  { apply B3. intros n' Hn'. injection Hn' as <-. lia. }
  assert (CL : Forall2 (cnt_ok rho (ev rho n)) sl (cl c)).
  { apply A3. intros n' Hn'. destruct (B2 n' Hn') as [n'' [E Hle]]. injection E as <-. exact Hle. }
  destruct (new_side_spec rho base n _ _ _ H3 Hwl Hfl CL Hn1) as [L1 L2].
  destruct (new_side_spec rho base n _ _ _ H4 Hwr Hfr CR Hn1) as [R1 R2].
  pose proof (iterV T c sl sr HR (pred (N.to_nat (ev rho n))) rho _ _ L1 R1) as Hit.
  replace (S (pred (N.to_nat (ev rho n)))) with (N.to_nat (ev rho n)) in Hit by lia.
  unfold den, fillc in *. cbn [cq cd cl cr].
  rewrite L2, R2, !inst_fillw. exact Hit.
Qed.

Lemma mkslots_fixeq gf extra ds p xs : Forall2 fixeq (mkslots gf extra ds p xs) xs.
Proof.
  revert p; induction xs as [| [w x] xs IH]; intros p; cbn; constructor; [| apply IH].
  unfold mkslot. destruct (dlook p ds) as [[[] m] |]; cbn; [exact I | exact I |].
  destruct gf; cbn; [exact I | reflexivity].
Qed.

(** * The checked run *)

Inductive act := P (k : N) (gf : bool) (extra : N) (ds : list dl) (sub : list act) (subk : N) (ap : bool).

Fixpoint steps (T : TM) (n : nat) (c : conf lin) (p : bool) : option (conf lin * bool) :=
  match n with
  | O => Some (c, p)
  | S n' => match bmove T c with Some (c', p') => steps T n' c' (p || p') | None => None end
  end.

Fixpoint run (T : TM) (fuel : nat) (depth : N) (c : conf lin) (tr : list act) (kf : N) (p : bool)
  : option (conf lin * bool) :=
  match fuel with
  | O => None
  | S f =>
    match tr with
    | [] => steps T (N.to_nat kf) c p
    | P k gf ex ds sub subk ap :: tr' =>
      match steps T (N.to_nat k) c p with
      | None => None
      | Some (c1, p1) =>
        let base := 1000 * (depth + 1) in
        let sl := mkslots gf ex ds 0 (cl c1) in
        let sr := mkslots gf ex ds 500 (cr c1) in
        if wf_rule base c1 sl sr then
          match run T f (depth + 1) (lhs base c1 sl sr) sub subk false with
          | None => None
          | Some (c2, _) =>
            if confeqb c2 (rhs base c1 sl sr) then
              if ap then
                match apply c1 sl sr with
                | None => None
                | Some c3 => run T f depth c3 tr' kf p1
                end
              else run T f depth c1 tr' kf p1
            else None
          end
        else None
      end
    end
  end.

Definition Reach T c c' p p' := forall rho,
  den rho c -[ T ]->* den rho c' /\ (p' = true -> p = true \/ den rho c -[ T ]->+ den rho c').

Lemma Reach_trans T c1 c2 c3 p1 p2 p3 : Reach T c1 c2 p1 p2 -> Reach T c2 c3 p2 p3 -> Reach T c1 c3 p1 p3.
Proof.
  intros H1 H2 rho. destruct (H1 rho) as [A1 B1]. destruct (H2 rho) as [A2 B2].
  split; [eapply evstep_trans; eassumption |]. intros Hp.
  destruct (B2 Hp) as [Hp2 | Hp2].
  - destruct (B1 Hp2) as [Hp1 | Hp1]; [left; exact Hp1 | right; eapply progress_evstep_trans; eassumption].
  - right. eapply evstep_progress_trans; eassumption.
Qed.

Lemma Reach_refl T c p : Reach T c c p p.
Proof. intros rho. split; [apply evstep_refl | left; assumption]. Qed.

Lemma steps_spec T n c p c' p' : steps T n c p = Some (c', p') -> Reach T c c' p p'.
Proof.
  revert c p. induction n as [| n IH]; intros c p H; cbn in H.
  - injection H as <- <-. apply Reach_refl.
  - destruct (bmove T c) as [[c1 p1] |] eqn:Hb; [| discriminate].
    apply (Reach_trans _ _ c1 _ _ (p || p1)); [| apply IH; exact H].
    intros rho. destruct (bmove_spec _ _ _ _ Hb rho) as [A B]. split; [exact A |].
    intros Hp. destruct p; [left; reflexivity |]. right. apply B. exact Hp.
Qed.

Lemma run_spec T fuel : forall depth c tr kf p c' p',
  run T fuel depth c tr kf p = Some (c', p') -> Reach T c c' p p'.
Proof.
  induction fuel as [| f IH]; intros depth c tr kf p c' p' H; [discriminate |].
  cbn [run] in H. destruct tr as [| [k gf ex ds sub subk ap] tr'].
  - apply steps_spec with (n := N.to_nat kf). exact H.
  - destruct (steps T (N.to_nat k) c p) as [[c1 p1] |] eqn:Hs; [| discriminate].
    apply steps_spec in Hs.
    set (base := 1000 * (depth + 1)) in H.
    set (sl := mkslots gf ex ds 0 (cl c1)) in H.
    set (sr := mkslots gf ex ds 500 (cr c1)) in H.
    destruct (wf_rule base c1 sl sr) eqn:Hwf; [| discriminate].
    destruct (run T f (depth + 1) (lhs base c1 sl sr) sub subk false) as [[c2 p2] |] eqn:Hsub; [| discriminate].
    destruct (confeqb c2 (rhs base c1 sl sr)) eqn:Heq; [| discriminate].
    apply confeqb_eq in Heq. subst c2.
    apply IH in Hsub.
    assert (HR : RuleV T c1 sl sr).
    { apply (ruleV_of_run T base); [exact Hwf |]. intros rho. apply (Hsub rho). }
    apply (Reach_trans _ _ _ _ _ p1 _ Hs).
    destruct ap.
    + destruct (apply c1 sl sr) as [c3 |] eqn:Ha; [| discriminate].
      apply (Reach_trans _ _ c3 _ _ p1); [| eapply IH; exact H].
      unfold wf_rule in Hwf.
      repeat match goal with H : _ && _ = true |- _ => apply andb_prop in H as [? ?] end.
      intros rho. split; [| left; assumption].
      eapply (apply_spec T base c1 sl sr); try eassumption; apply mkslots_fixeq.
    + eapply IH. exact H.
Qed.

Theorem run_progress T fuel c tr kf c' :
  run T fuel 0 c tr kf false = Some (c', true) -> forall rho, den rho c -[ T ]->+ den rho c'.
Proof.
  intros H rho. destruct (run_spec _ _ _ _ _ _ _ _ _ H rho) as [_ B].
  destruct (B eq_refl) as [Hf | Hp]; [discriminate | exact Hp].
Qed.

Theorem run_reach T fuel c tr kf p c' p' :
  run T fuel 0 c tr kf p = Some (c', p') -> forall rho, den rho c -[ T ]->* den rho c'.
Proof. intros H rho. apply (run_spec _ _ _ _ _ _ _ _ _ H rho). Qed.

