From Coq Require Import String.
Definition tm := Eval compute in (TM_from_str "1RB1LB_1RC0LA_1RD0RE_1LA0LB_1RF---_1RB1LD"%string).

Definition fuel : nat := N.to_nat 1000000.

Definition chk (T : TM) (c : conf lin) (tr : list act) (kf : N) (c' : conf lin) (p : bool) : bool :=
  match run T fuel 0 c tr kf false with
  | Some (c2, p2) => confeqb c2 c' && (if p then p2 else true)
  | None => false
  end.

Lemma chk_progress T c tr kf c' : chk T c tr kf c' true = true -> forall rho, den rho c -[ T ]->+ den rho c'.
Proof.
  unfold chk. destruct (run T fuel 0 c tr kf false) as [[c2 [|]] |] eqn:E; intros H;
    [| apply andb_prop in H as [_ H]; discriminate | discriminate].
  apply andb_prop in H as [H _]. apply confeqb_eq in H. subst c2.
  exact (run_progress _ _ _ _ _ _ E).
Qed.

Lemma prog_eq T a b a' b' : a -[ T ]->+ b -> a = a' -> b = b' -> a' -[ T ]->+ b'.
Proof. intros H -> ->. exact H. Qed.

Definition Ncf (e : lin) : conf lin :=
  Cf A L [([S1;S0;S1;S1], e); ([S0;S0;S0;S1], LN 1 [])]
         [([S0;S0;S0;S1], LN 28 []); ([S0;S0;S1;S1], LN 1 []); ([S0;S0;S0;S0], LN 1 []); ([S1;S0;S0;S0], LN 1 [])].

Definition tpN (n : N) : Q * tape := den (fun _ => 0) (Ncf (LN n [])).

Lemma ev_const rho n : ev rho (LN n []) = n.
Proof. unfold ev; cbn [lc lv sumc]. apply N.add_0_r. Qed.

Lemma ev1 rho k v (p : positive) : ev rho (LN k [(v, p)]) = k + Npos p * rho v.
Proof. unfold ev; cbn [lc lv sumc]. lia. Qed.

Lemma den_Ncf rho e : den rho (Ncf e) = tpN (ev rho e).
Proof. unfold tpN, den, Ncf; cbn [cq cd cl cr inst map]. rewrite !ev_const. reflexivity. Qed.

Lemma chkN_ok : chk tm tr_N_in tr_N_tr tr_N_kf tr_N_out true = true.
Proof. vm_compute. reflexivity. Qed.

Lemma lemN m : tpN (m + 22) -[ tm ]->+ tpN (262144 * m + 38626190).
Proof.
  pose proof (chk_progress _ _ _ _ _ chkN_ok (fun _ => m)) as P.
  change tr_N_in with (Ncf (LN 22 [(0, 1%positive)])) in P.
  change tr_N_out with (Ncf (LN 38626190 [(0, 262144%positive)])) in P.
  rewrite !den_Ncf, !ev1 in P.
  eapply prog_eq; [exact P | f_equal; lia | f_equal; lia].
Qed.

Lemma chkA_ok : chk tm tr_A_in tr_A_tr tr_A_kf tr_A_out true = true.
Proof. vm_compute. reflexivity. Qed.

Lemma opening : c0 -[ tm ]->+ tpN 508932094.
Proof.
  pose proof (chk_progress _ _ _ _ _ chkA_ok (fun _ => 0)) as P.
  change tr_A_out with (Ncf (LN 508932094 [])) in P.
  rewrite den_Ncf, ev_const in P.
  exact P.
Qed.

Lemma nonhalt : ~ halts tm c0.
Proof.
  apply progress_nonhalt with (P := fun c => c = c0 \/ exists m, c = tpN (m + 22)).
  - intros c [-> | [m ->]].
    + exists (tpN 508932094). split; [right; exists 508932072; f_equal; lia | exact opening].
    + exists (tpN (262144 * m + 38626190)). split.
      * right. exists (262144 * m + 38626168). f_equal. lia.
      * apply lemN.
  - left. reflexivity.
Qed.
